/* Editable modulation rows; retain the existing serialized fields for compatibility. */
(()=>{'use strict';const $=id=>document.getElementById(id),am=$('amRows'),degs=$('relModes');am.closest('details').hidden=true;degs.closest('details').hidden=true;
const section=document.createElement('section');section.id='modulationEditor';section.innerHTML=`<h2>เปรียบเทียบ Availability หลาย Modulation</h2><p class="note">หนึ่งแถวต่อโหมด · ใช้พิกัด DEM และภูมิอากาศร่วมกัน คำนวณทุกแถวพร้อมกันเมื่อกดปุ่มคำนวณลิงก์ · TX/RX threshold ต้องอิง datasheet ของ bandwidth และ BER ที่เลือก</p><div class="mode-actions"><button type="button" id="addMode">เพิ่ม modulation</button><button type="button" id="copyMainMode">เพิ่มจากค่าหลัก</button></div><div class="availability-scroll"><table id="modeEditorTable"><thead><tr><th>Modulation</th><th>ความจุ Mbps</th><th>TX A dBm</th><th>TX B dBm</th><th>RX threshold A dBm</th><th>RX threshold B dBm</th><th>XPD multipath dB</th><th>XPD rain dB</th><th>จัดการ</th></tr></thead><tbody></tbody></table></div><p id="modeCount" role="status" class="note"></p><p class="note">Degradation ใช้ร่วมกันทั้งสองทิศทางของโหมดนั้น · ว่าง = ยังไม่ทราบ / 0 = ยืนยันว่าไม่เผื่อ · หากไม่มีแถว จะคำนวณด้วย modulation หลักด้านบน · ความจุเป็นค่าที่ผู้ใช้กำหนด ไม่ได้คำนวณจากชื่อ QAM และไม่รวมเป็น availability ของ 2+0 โดยอัตโนมัติ</p>`;
$('availabilityInputs').after(section);const body=section.querySelector('tbody');
const names=['Modulation','ความจุ Mbps','TX A dBm','TX B dBm','RX threshold A dBm','RX threshold B dBm','XPD multipath dB','XPD rain dB'];
function sync(){const rows=[...body.rows],seen=new Set();const data=[],degradation=[];for(const row of rows){const inputs=[...row.querySelectorAll('input')],v=inputs.map(x=>x.value.trim()),key=v[0].toLowerCase();inputs[0].setCustomValidity(!v[0]?'กรอกชื่อ modulation':/[,\n]/.test(v[0])?'ชื่อโหมดห้ามมี comma หรือขึ้นบรรทัดใหม่':seen.has(key)?'ชื่อ modulation ซ้ำ กรุณาตั้งชื่อให้ต่างกัน':'');seen.add(key);data.push(v.slice(0,6).join(','));if(v[6]!==''||v[7]!=='')degradation.push([v[0],v[6],v[7]].join(','))}am.value=data.join('\n');degs.value=degradation.join('\n');$('modeCount').textContent=rows.length?`${rows.length} modulation · กดคำนวณลิงก์เพื่ออัปเดตผลทุกแถว`:'ไม่มีแถว · ใช้ค่าของ modulation หลัก';}
function append(values){const row=body.insertRow();names.forEach((name,i)=>{const cell=row.insertCell(),input=document.createElement('input');input.type=i?'number':'text';input.step='any';input.value=values[i]??'';input.setAttribute('aria-label',name);if(i<6)input.required=true;if(i===0)input.maxLength=60;if(i===1||i>=6)input.min='0';if(i===4||i===5)input.max='0';if(i>=6)input.max='100';cell.append(input)});const del=document.createElement('button');del.type='button';del.textContent='ลบ';del.setAttribute('aria-label','ลบ modulation');del.onclick=()=>{row.remove();sync();dirty()};row.insertCell().append(del);return row;}
function restore(){body.replaceChildren();const map=Object.create(null);for(const line of degs.value.split('\n')){const v=line.split(',');if(v[0])map[v[0].trim()]=v.slice(1)}for(const line of am.value.split('\n').filter(x=>x.trim())){const v=line.split(',').map(x=>x.trim());append([...v,...(map[v[0]]||['',''])])}sync();}
$('addMode').onclick=()=>{append(['','','','','','','','']);sync();dirty()};
$('copyMainMode').onclick=()=>{const name=$('modulation').value;const power=side=>RFPower.dbm(Number($(side+'Power').value),$(side+'PowerUnit').value);append([name,$('capacity').value,power('a'),power('b'),$('aThreshold').value,$('bThreshold').value,$('relMpDeg').value,$('relRainDeg').value]);sync();dirty()};
section.addEventListener('input',sync);const prev=$('example').onclick;$('example').onclick=()=>{prev();restore()};restore();
globalThis.MWModulationsUI={restore,replace(values){body.replaceChildren();values.forEach(append);sync();dirty()}};
})();
